// GestionEmployes v2.4 - UTF-8
import { useState } from "react";

var T={bg:"#F5F3EE",surface:"#FFF",alt:"#EDEBE4",border:"#DDD9CF",text:"#1C1A17",muted:"#7C7568",accent:"#1B5E3B",accentL:"#E8F2EC",navy:"#13233A",blue:"#1A56DB",blueL:"#EFF6FF",amber:"#B86020",amberL:"#FEF3E2",red:"#B83232",redL:"#FDECEA",purple:"#6B3FA0",purpleL:"#F3EFFA"};
var INP={width:"100%",border:"1px solid #DDD9CF",borderRadius:7,padding:"7px 10px",fontSize:12,fontFamily:"inherit",background:"#FFF",outline:"none",boxSizing:"border-box"};
var money=function(n){return Math.abs(n||0).toLocaleString("fr-CA",{minimumFractionDigits:2,maximumFractionDigits:2})+" $";};

function Btn(p){return <button onClick={p.onClick} disabled={p.dis} style={{background:p.bg||T.accent,border:p.bdr||"none",borderRadius:7,padding:p.sm?"5px 11px":"8px 16px",color:p.tc||"#fff",fontSize:p.sm?10:12,fontWeight:600,cursor:p.dis?"not-allowed":"pointer",opacity:p.dis?0.5:1,fontFamily:"inherit"}}>{p.children}</button>;}
function Lbl(p){return <div style={{fontSize:10,color:T.muted,textTransform:"uppercase",letterSpacing:"0.07em",fontWeight:600,marginBottom:5}}>{p.l}</div>;}
function Card(p){return <div style={{background:T.surface,border:"1px solid "+T.border,borderRadius:10,padding:16,marginBottom:12}}>{p.children}</div>;}
function Badge(p){var colors={actif:{bg:T.accentL,c:T.accent},inactif:{bg:T.redL,c:T.red},congé:{bg:T.amberL,c:T.amber},essai:{bg:T.blueL,c:T.blue}};var col=colors[p.s]||colors.actif;return <span style={{background:col.bg,color:col.c,borderRadius:20,padding:"2px 10px",fontSize:10,fontWeight:700}}>{p.s}</span>;}

var ROLES_EMP=[
  {id:"admin",l:"Administrateur Predictek",color:T.purple},
  {id:"gestionnaire",l:"Gestionnaire",color:T.blue},
  {id:"comptable",l:"Comptable",color:T.accent},
  {id:"support",l:"Support technique",color:T.amber},
  {id:"lecture",l:"Lecture seule",color:T.muted},
];

var DEPTS=["Direction","Administration","Opérations","Comptabilité","Terrain","Support"];
var STATUTS=["actif","inactif","congé","essai"];
var EMP_VIDE={prenom:"",nom:"",courriel:"",tel:"",poste:"",dept:"Administration",role:"gestionnaire",statut:"actif",salaire:"",dateEmbauche:"",notes:""};

function TabEmployes(){
  var s0=useState([]);var emps=s0[0];var setEmps=s0[1];
  var s1=useState(null);var sel=s1[0];var setSel=s1[1];
  var s2=useState(false);var showForm=s2[0];var setShowForm=s2[1];
  var s3=useState(EMP_VIDE);var form=s3[0];var setForm=s3[1];
  var s4=useState("");var search=s4[0];var setSearch=s4[1];

  function sf(k,v){setForm(function(o){var n=Object.assign({},o);n[k]=v;return n;});}
  var filtered=emps.filter(function(e){var q=search.toLowerCase();return !q||(e.prenom+" "+e.nom).toLowerCase().includes(q)||e.courriel.toLowerCase().includes(q)||e.dept.toLowerCase().includes(q);});

  function sauvegarder(){
    if(!form.prenom||!form.nom||!form.courriel)return;
    if(form.id){setEmps(function(prev){return prev.map(function(e){return e.id===form.id?Object.assign({},form):e;});});}
    else{setEmps(function(prev){return prev.concat([Object.assign({},form,{id:Date.now()})]);});}
    setShowForm(false);setForm(EMP_VIDE);setSel(null);
  }
  function supprimer(id){setEmps(function(prev){return prev.filter(function(e){return e.id!==id;});});setSel(null);}

  return(
    <div style={{display:"grid",gridTemplateColumns:sel?"1fr 340px":"1fr",gap:16}}>
      <div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
          <div>
            <div style={{fontSize:18,fontWeight:800,color:T.navy,fontFamily:"Georgia,serif"}}>Employés</div>
            <div style={{fontSize:11,color:T.muted}}>{emps.filter(function(e){return e.statut==="actif";}).length} actif(s) sur {emps.length} employé(s)</div>
          </div>
          <div style={{display:"flex",gap:8,alignItems:"center"}}>
            <input value={search} onChange={function(e){setSearch(e.target.value);}} placeholder="Rechercher..." style={Object.assign({},INP,{width:200})}/>
            <Btn onClick={function(){setShowForm(true);setForm(EMP_VIDE);setSel(null);}}>+ Nouvel employé</Btn>
          </div>
        </div>
        {emps.length===0?(
          <div style={{background:T.alt,border:"1px solid "+T.border,borderRadius:10,padding:40,textAlign:"center",color:T.muted}}>
            <div style={{fontSize:32,marginBottom:12}}>👥</div>
            <div style={{fontSize:14,fontWeight:600,color:T.navy,marginBottom:6}}>Aucun employé</div>
            <div style={{fontSize:12,marginBottom:16}}>Ajoutez votre premier employé pour commencer</div>
            <Btn onClick={function(){setShowForm(true);setForm(EMP_VIDE);}}>+ Ajouter un employé</Btn>
          </div>
        ):(
          <div style={{background:T.surface,border:"1px solid "+T.border,borderRadius:10,overflow:"hidden"}}>
            <table style={{width:"100%",borderCollapse:"collapse"}}>
              <thead><tr style={{background:T.alt}}>{["Employé","Poste / Département","Rôle","Salaire","Statut",""].map(function(h){return <th key={h} style={{padding:"8px 12px",textAlign:"left",fontSize:10,fontWeight:700,color:T.muted,textTransform:"uppercase"}}>{h}</th>;})}</tr></thead>
